package org.apache.parquet.hadoop;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Path;
import org.apache.hadoop.conf.Configuration;
import org.apache.parquet.column.ColumnDescriptor;
import org.apache.parquet.column.page.DataPage;
import org.apache.parquet.column.page.PageReadStore;
import org.apache.parquet.column.page.PageReader;
import org.apache.parquet.example.data.Group;
import org.apache.parquet.example.data.simple.SimpleGroup;
import org.apache.parquet.hadoop.ParquetFileReader;
import org.apache.parquet.hadoop.example.ExampleParquetWriter;
import org.apache.parquet.hadoop.util.HadoopInputFile;
import org.apache.parquet.schema.MessageType;
import org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName;
import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class ParquetFileReaderReadAllPagesTests {

  @TempDir
  Path temporaryDirectory;

  @Test
  void readAllPagesReturnsAllDataPagesAndTheirValueCounts() throws Exception {
    MessageType schema =
        Types.buildMessage()
            .required(PrimitiveTypeName.INT32)
            .named("value")
            .named("schema");

    Configuration configuration = new Configuration();
    Path parquetFile = temporaryDirectory.resolve("read-all-pages.parquet");
    org.apache.hadoop.fs.Path parquetPath =
        new org.apache.hadoop.fs.Path(parquetFile.toUri());

    try (var writer =
        ExampleParquetWriter.builder(parquetPath)
            .withConf(configuration)
            .withType(schema)
            .build()) {
      for (int value = 0; value < 10; value++) {
        Group row = new SimpleGroup(schema);
        row.add("value", value);
        writer.write(row);
      }
    }

    ColumnDescriptor column = schema.getColumnDescription(new String[] {"value"});

    try (ParquetFileReader reader =
        ParquetFileReader.open(HadoopInputFile.fromPath(parquetPath, configuration))) {
      PageReadStore rowGroup = reader.readNextRowGroup();

      assertNotNull(rowGroup, "The written rows must produce a row group");

      PageReader pageReader = rowGroup.getPageReader(column);

      assertNotNull(pageReader, "The column must have a page reader");
      assertEquals(
          10L,
          pageReader.getTotalValueCount(),
          "readAllPages must report the complete column value count");

      long valuesReadFromPages = 0L;
      int pageCount = 0;
      DataPage page;
      while ((page = pageReader.readPage()) != null) {
        valuesReadFromPages += page.getValueCount();
        pageCount++;
      }

      assertTrue(pageCount > 0, "readAllPages must return at least one data page");
      assertEquals(
          10L,
          valuesReadFromPages,
          "The returned pages must contain every value in the column chunk");
    }
  }
}
